SELECT package_name, version, publisher, published_at, DATEDIFF(published_at, prev_at) AS gap_days FROM (SELECT package_name, version, publisher, published_at, LAG(published_at) OVER (PARTITION BY package_name ORDER BY published_at) AS prev_at, MIN(published_at) OVER (PARTITION BY package_name, publisher) AS publisher_first_seen FROM pkgtrail.releases_table WHERE publisher <> '') t WHERE published_at = publisher_first_seen AND prev_at IS NOT NULL AND DATEDIFF(published_at, prev_at) > 180 ORDER BY package_name, published_at
